import { QueryRunner } from 'typeorm';
import { AddInstallMetadata1775700000000 } from './1775700000000-AddInstallMetadata';

describe('AddInstallMetadata1775700000000', () => {
  let migration: AddInstallMetadata1775700000000;
  let queryRunner: jest.Mocked<Pick<QueryRunner, 'query'>>;

  beforeEach(() => {
    migration = new AddInstallMetadata1775700000000();
    queryRunner = { query: jest.fn().mockResolvedValue(undefined) };
  });

  describe('up', () => {
    it('creates the install_metadata table', async () => {
      await migration.up(queryRunner as unknown as QueryRunner);

      expect(queryRunner.query).toHaveBeenCalledTimes(1);
      const sql = queryRunner.query.mock.calls[0][0] as string;
      expect(sql).toContain('CREATE TABLE "install_metadata"');
      expect(sql).toContain('"id" varchar NOT NULL');
      expect(sql).toContain('"install_id" varchar NOT NULL');
      expect(sql).toContain('"first_send_at" timestamp');
      expect(sql).toContain('"last_sent_at" timestamp');
      expect(sql).toContain('PRIMARY KEY ("id")');
    });
  });

  describe('down', () => {
    it('drops the install_metadata table', async () => {
      await migration.down(queryRunner as unknown as QueryRunner);

      expect(queryRunner.query).toHaveBeenCalledTimes(1);
      const sql = queryRunner.query.mock.calls[0][0] as string;
      expect(sql).toContain('DROP TABLE "install_metadata"');
    });
  });

  it('exposes a stable migration name', () => {
    expect(migration.name).toBe('AddInstallMetadata1775700000000');
  });
});

import { ModelPricingCacheService } from './model-pricing-cache.service';
import { PricingSyncService, OpenRouterPricingEntry } from '../database/pricing-sync.service';
import { ModelsDevSyncService } from '../database/models-dev-sync.service';
import { ProviderModelRegistryService } from '../model-discovery/provider-model-registry.service';
import { PROVIDER_BY_ID } from '../common/constants/providers';
import { normalizeProviderName } from 'manifest-shared';

/**
 * A price belongs to a (provider, model) pair, not to a model.
 *
 * 24 providers publish a `deepseek-v4-pro` record. The shared cache is keyed by
 * model name alone, so they all write to one key and the last one — OpenCode
 * Zen, which sits far later in the registry than DeepSeek — is the one that
 * survives. Costing a DeepSeek request off that entry charges the user a
 * reseller's rate and drops DeepSeek's peak-hour schedule with it.
 */

const DEEPSEEK_TIME_TIER = {
  windows: ['01:00-04:00', '06:00-10:00'],
  days: [1, 2, 3, 4, 5],
  inputPricePerToken: 1.32 / 1_000_000,
  outputPricePerToken: 3.96 / 1_000_000,
  cacheReadPricePerToken: 0.044 / 1_000_000,
  cacheWritePricePerToken: null,
};

/** DeepSeek's own rates: real off-peak base plus the weekday peak band. */
const DEEPSEEK_OWN = {
  id: 'deepseek-v4-pro',
  name: 'DeepSeek V4 Pro',
  inputPricePerToken: 0.66 / 1_000_000,
  outputPricePerToken: 1.98 / 1_000_000,
  cacheReadPricePerToken: 0.022 / 1_000_000,
  timeTiers: [DEEPSEEK_TIME_TIER],
};

/** The reseller's rate for the same model: higher, flat, no schedule. */
const ZEN_RESALE = {
  id: 'deepseek-v4-pro',
  name: 'DeepSeek V4 Pro',
  inputPricePerToken: 1.74 / 1_000_000,
  outputPricePerToken: 3.84 / 1_000_000,
  cacheReadPricePerToken: 0.145 / 1_000_000,
};

/** A second reseller, with a multi-word display name and its own rate. */
const GO_RESALE = {
  id: 'deepseek-v4-pro',
  name: 'DeepSeek V4 Pro',
  inputPricePerToken: 0.9 / 1_000_000,
  outputPricePerToken: 2.4 / 1_000_000,
};

/** Catalogued under a bare id; agents often send it with a date suffix. */
const ANTHROPIC_DATED = {
  id: 'claude-opus-4-6',
  name: 'Claude Opus 4.6',
  inputPricePerToken: 5 / 1_000_000,
  outputPricePerToken: 25 / 1_000_000,
};

describe('ModelPricingCacheService — pricing scoped to the provider that served the request', () => {
  let service: ModelPricingCacheService;

  const build = (orCache = new Map<string, OpenRouterPricingEntry>()) => {
    const mockPricingSync = {
      getAll: jest.fn().mockReturnValue(orCache),
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    const mockModelsDevSync = {
      lookupModel: jest.fn().mockReturnValue(null),
      getModelsForProvider: jest.fn().mockImplementation((providerId: string) => {
        if (providerId === 'deepseek') return [DEEPSEEK_OWN];
        if (providerId === 'opencode-zen') return [ZEN_RESALE];
        if (providerId === 'anthropic') return [ANTHROPIC_DATED];
        if (providerId === 'opencode-go') return [GO_RESALE];
        return [];
      }),
      isProviderSupported: jest.fn().mockReturnValue(false),
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    const mockRegistry = {
      isModelConfirmed: jest.fn().mockReturnValue(null),
      getConfirmedModels: jest.fn().mockReturnValue(null),
      registerModels: jest.fn(),
    };
    return new ModelPricingCacheService(
      mockPricingSync as unknown as PricingSyncService,
      mockModelsDevSync as unknown as ModelsDevSyncService,
      mockRegistry as unknown as ProviderModelRegistryService,
    );
  };

  beforeEach(() => {
    service = build();
  });

  it('returns the reseller entry when no provider is named', async () => {
    await service.reload();

    // Unscoped lookup is last-writer-wins. OpenCode Zen is registered after
    // DeepSeek, so this is the pre-existing behaviour, pinned deliberately.
    const entry = service.getByModel('deepseek-v4-pro');
    expect(entry!.provider).toBe('OpenCode Zen');
    expect(entry!.input_price_per_token).toBe(1.74 / 1_000_000);
  });

  it("returns DeepSeek's own rates when the request was served by DeepSeek", async () => {
    await service.reload();

    const entry = service.getByModel('deepseek-v4-pro', 'deepseek');
    expect(entry!.provider).toBe('DeepSeek');
    expect(entry!.input_price_per_token).toBe(0.66 / 1_000_000);
    expect(entry!.output_price_per_token).toBe(1.98 / 1_000_000);
  });

  it("carries DeepSeek's weekday peak schedule on the scoped entry", async () => {
    await service.reload();

    const tiers = service.getByModel('deepseek-v4-pro', 'deepseek')!.time_tiers;
    expect(tiers).toHaveLength(1);
    expect(tiers![0].days).toEqual([1, 2, 3, 4, 5]);
    expect(tiers![0].input_price_per_token).toBe(1.32 / 1_000_000);
  });

  it('gives the reseller its own flat rate with no borrowed schedule', async () => {
    await service.reload();

    // OpenCode Zen bills a flat rate. DeepSeek's peak hours are not theirs.
    const entry = service.getByModel('deepseek-v4-pro', 'opencode-zen');
    expect(entry!.provider).toBe('OpenCode Zen');
    expect(entry!.input_price_per_token).toBe(1.74 / 1_000_000);
    expect(entry!.time_tiers).toBeUndefined();
  });

  it('accepts a provider alias as well as its canonical id', async () => {
    await service.reload();

    expect(service.getByModel('deepseek-v4-pro', 'DeepSeek')!.provider).toBe('DeepSeek');
  });

  it('falls back to the shared entry when the named provider publishes no price', async () => {
    await service.reload();

    // A missing cost reads as "free" on every dashboard, so an approximate
    // number beats no number at all.
    const entry = service.getByModel('deepseek-v4-pro', 'huggingface');
    expect(entry).toBeDefined();
    expect(entry!.provider).toBe('OpenCode Zen');
  });

  it('falls back to the shared entry when the provider is not in the registry', async () => {
    await service.reload();

    expect(service.getByModel('deepseek-v4-pro', 'not-a-provider')!.provider).toBe('OpenCode Zen');
  });

  it('scopes OpenRouter entries to OpenRouter, never to the lab', async () => {
    const orCache = new Map<string, OpenRouterPricingEntry>([
      [
        'deepseek/deepseek-v4-pro',
        {
          input: 0.9 / 1_000_000,
          output: 2.4 / 1_000_000,
          displayName: 'DeepSeek V4 Pro',
        } as OpenRouterPricingEntry,
      ],
    ]);
    service = build(orCache);
    await service.reload();

    // Pricing follows transport: a request through the gateway is billed by
    // the gateway, at the gateway's rate.
    const viaGateway = service.getByModel('deepseek/deepseek-v4-pro', 'openrouter');
    expect(viaGateway!.input_price_per_token).toBe(0.9 / 1_000_000);
    // …and asking for OpenRouter's price must never hand back DeepSeek's.
    expect(service.getByModel('deepseek-v4-pro', 'openrouter')!.input_price_per_token).toBe(
      0.9 / 1_000_000,
    );
    expect(service.getByModel('deepseek-v4-pro', 'deepseek')!.input_price_per_token).toBe(
      0.66 / 1_000_000,
    );
  });

  it('resolves a dated model id to the provider-scoped catalogue entry', async () => {
    await service.reload();

    // Agents send `claude-opus-4-6-20260101`; the catalogue holds the bare id.
    // The scoped lookup has to normalise too, or every dated name would fall
    // through to the shared key and lose the provider it was asked about.
    const entry = service.getByModel('claude-opus-4-6-20260101', 'anthropic');
    expect(entry).toBeDefined();
    expect(entry!.provider).toBe('Anthropic');
    expect(entry!.input_price_per_token).toBe(5 / 1_000_000);
  });

  it("bills a vendor-qualified id at the lab's rate, not the gateway's", async () => {
    // An agent may send `anthropic/claude-opus-4-6` and route straight to
    // Anthropic. OpenRouter also publishes that exact key, so a lookup that
    // cannot reduce the prefixed name falls through to the gateway's entry —
    // which still carries the lab's display name, so the row looks correctly
    // attributed while holding the wrong seller's price.
    const orCache = new Map<string, OpenRouterPricingEntry>([
      [
        'anthropic/claude-opus-4-6',
        { input: 9 / 1_000_000, output: 45 / 1_000_000, displayName: 'Claude Opus 4.6' },
      ],
    ]);
    service = build(orCache as never);
    await service.reload();

    const entry = service.getByModel('anthropic/claude-opus-4-6', 'anthropic');
    expect(entry!.input_price_per_token).toBe(5 / 1_000_000);
    expect(entry!.source).toBe('models.dev');
  });

  it('accepts a provider display name, including multi-word ones', async () => {
    await service.reload();

    // Callers that hold a `PricingEntry.provider` have the display name, not
    // the registry id. `OpenCode Zen` and friends do not resolve by
    // lowercasing alone.
    // `OpenCode Go` is not the shared winner, so only a real display-name
    // resolution can return its rate rather than OpenCode Zen's.
    expect(service.getByModel('deepseek-v4-pro', 'OpenCode Go')!.input_price_per_token).toBe(
      0.9 / 1_000_000,
    );
    expect(service.getByModel('deepseek-v4-pro', 'DeepSeek')!.input_price_per_token).toBe(
      0.66 / 1_000_000,
    );
  });

  it.each([['OpenCode-Go'], ['opencode.go'], ['  OpenCode Go  '], ['opencodego'], ['OPENCODE GO']])(
    'resolves the punctuation variant %s to the same provider',
    async (written) => {
      // Free-form provider strings reach this from the playground and from
      // recorded telemetry. The rest of the backend matches them through
      // normalizeProviderName; a form that resolves everywhere else must not
      // quietly fall back to another seller's price here.
      //
      // OpenCode Go is deliberately not the shared-key winner, so this can
      // only pass through real resolution — asking for the winner would pass
      // even when resolution fails.
      await service.reload();

      const entry = service.getByModel('deepseek-v4-pro', written);
      expect(entry!.provider).toBe('OpenCode Go');
      expect(entry!.input_price_per_token).toBe(0.9 / 1_000_000);
    },
  );

  it('never points two providers at the same normalized display name', async () => {
    // The display-name index is first-writer-wins, so a collision would
    // silently resolve one provider's name to a different provider's price.
    const seen = new Map<string, string>();
    for (const [id, entry] of PROVIDER_BY_ID) {
      for (const key of [
        entry.displayName.toLowerCase(),
        normalizeProviderName(entry.displayName.toLowerCase()),
      ]) {
        const prior = seen.get(key);
        expect(prior === undefined || prior === id).toBe(true);
        seen.set(key, id);
      }
    }
  });

  it('drops a scoped entry when the provider stops listing the model', async () => {
    // reload() rebuilds from scratch. Without clearing the scoped map, a model
    // a provider has delisted would keep being priced from a stale rate.
    const models = new Map<string, unknown[]>([
      ['deepseek', [DEEPSEEK_OWN]],
      ['opencode-zen', [ZEN_RESALE]],
    ]);
    const mockModelsDevSync = {
      lookupModel: jest.fn().mockReturnValue(null),
      getModelsForProvider: jest.fn((providerId: string) => models.get(providerId) ?? []),
      isProviderSupported: jest.fn().mockReturnValue(false),
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    service = new ModelPricingCacheService(
      {
        getAll: jest.fn().mockReturnValue(new Map()),
        whenInitialized: jest.fn().mockResolvedValue(undefined),
      } as unknown as PricingSyncService,
      mockModelsDevSync as unknown as ModelsDevSyncService,
      {
        isModelConfirmed: jest.fn().mockReturnValue(null),
        getConfirmedModels: jest.fn().mockReturnValue(null),
        registerModels: jest.fn(),
      } as unknown as ProviderModelRegistryService,
    );

    await service.reload();
    expect(service.getByModel('deepseek-v4-pro', 'deepseek')!.provider).toBe('DeepSeek');

    models.set('deepseek', []);
    await service.reload();

    // DeepSeek no longer sells it, so the scoped hit is gone and the shared
    // entry answers instead.
    expect(service.getByModel('deepseek-v4-pro', 'deepseek')!.provider).toBe('OpenCode Zen');
  });
});

import { ModelPricingCacheService } from './model-pricing-cache.service';
import { PricingSyncService, OpenRouterPricingEntry } from '../database/pricing-sync.service';
import { ModelsDevSyncService } from '../database/models-dev-sync.service';
import { ProviderModelRegistryService } from '../model-discovery/provider-model-registry.service';

/**
 * Tests for the zero-pricing override protection in
 * `ModelPricingCacheService.loadModelsDevEntries()` (see source lines 217-222).
 *
 * Some providers (e.g. GitHub Copilot) ship a models.dev catalog that lists
 * popular third-party models like `gemini-2.5-pro` as $0. Without the guard,
 * those entries would erase the real pricing that came in either from
 * OpenRouter or from an earlier iteration of the models.dev loop. These
 * tests pin the cross-source behavior so the conditional cannot regress
 * silently.
 */

function makeEntry(input: number, output: number): OpenRouterPricingEntry {
  return { input, output };
}

function makeMockRegistry() {
  return {
    isModelConfirmed: jest.fn().mockReturnValue(null),
    getConfirmedModels: jest.fn().mockReturnValue(null),
    registerModels: jest.fn(),
  };
}

function makeMockModelsDevSync() {
  return {
    lookupModel: jest.fn().mockReturnValue(null),
    getModelsForProvider: jest.fn().mockReturnValue([]),
    isProviderSupported: jest.fn().mockReturnValue(false),
    whenInitialized: jest.fn().mockResolvedValue(undefined),
  };
}

describe('ModelPricingCacheService — zero-pricing override protection', () => {
  let service: ModelPricingCacheService;
  let mockGetAll: jest.Mock;
  let mockRegistry: ReturnType<typeof makeMockRegistry>;
  let mockModelsDevSync: ReturnType<typeof makeMockModelsDevSync>;
  let mockPricingSync: { getAll: jest.Mock; whenInitialized: jest.Mock };

  beforeEach(() => {
    mockGetAll = jest.fn().mockReturnValue(new Map<string, OpenRouterPricingEntry>());
    mockPricingSync = {
      getAll: mockGetAll,
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    mockModelsDevSync = makeMockModelsDevSync();
    mockRegistry = makeMockRegistry();
    service = new ModelPricingCacheService(
      mockPricingSync as unknown as PricingSyncService,
      mockModelsDevSync as unknown as ModelsDevSyncService,
      mockRegistry as unknown as ProviderModelRegistryService,
    );
  });

  describe('OpenRouter real pricing vs models.dev zero pricing', () => {
    it('keeps OpenRouter pricing on the bare key when models.dev lists $0 for the same model', async () => {
      // OpenRouter: real pricing for google/gemini-2.5-pro
      mockGetAll.mockReturnValue(
        new Map<string, OpenRouterPricingEntry>([
          ['google/gemini-2.5-pro', makeEntry(0.001, 0.01)],
        ]),
      );

      // models.dev: GitHub Copilot exposes gemini-2.5-pro as $0 (acts as a
      // proxy — its own pricing for the same model is not relevant).
      mockModelsDevSync.getModelsForProvider.mockImplementation((providerId: string) => {
        if (providerId === 'copilot') {
          return [
            {
              id: 'gemini-2.5-pro',
              name: 'Gemini 2.5 Pro',
              inputPricePerToken: 0,
              outputPricePerToken: 0,
            },
          ];
        }
        return [];
      });

      await service.reload();

      // The bare key (used by cost lookup on ingested messages that only
      // carry the model name) must still resolve to OpenRouter's real
      // pricing — NOT the $0 entry from copilot's models.dev catalog.
      const bare = service.getByModel('gemini-2.5-pro');
      expect(bare).toBeDefined();
      expect(bare!.source).toBe('openrouter');
      expect(bare!.provider).toBe('Google');
      expect(bare!.input_price_per_token).toBe(0.001);
      expect(bare!.output_price_per_token).toBe(0.01);
    });

    it('lets models.dev override OpenRouter when the new pricing is non-zero', async () => {
      // Inverse case: OpenRouter has zero pricing, models.dev has real
      // pricing. The guard should NOT block this — zero is the bad data,
      // not the good data.
      mockGetAll.mockReturnValue(
        new Map<string, OpenRouterPricingEntry>([['google/gemini-2.5-pro', makeEntry(0, 0)]]),
      );

      mockModelsDevSync.getModelsForProvider.mockImplementation((providerId: string) => {
        if (providerId === 'gemini') {
          return [
            {
              id: 'gemini-2.5-pro',
              name: 'Gemini 2.5 Pro',
              inputPricePerToken: 0.00000125,
              outputPricePerToken: 0.00001,
            },
          ];
        }
        return [];
      });

      await service.reload();

      const bare = service.getByModel('gemini-2.5-pro');
      expect(bare).toBeDefined();
      expect(bare!.source).toBe('models.dev');
      expect(bare!.provider).toBe('Google');
      expect(bare!.input_price_per_token).toBe(0.00000125);
      expect(bare!.output_price_per_token).toBe(0.00001);
    });

    it('lets models.dev override OpenRouter when both have real pricing', async () => {
      // Sanity: the guard ONLY kicks in for $0 incoming pricing. When
      // models.dev has its own real pricing for a model, it should still
      // win over OpenRouter (curated > broad).
      mockGetAll.mockReturnValue(
        new Map<string, OpenRouterPricingEntry>([
          ['anthropic/claude-opus-4-6', makeEntry(0.000015, 0.000075)],
        ]),
      );

      mockModelsDevSync.getModelsForProvider.mockImplementation((providerId: string) => {
        if (providerId === 'anthropic') {
          return [
            {
              id: 'claude-opus-4-6',
              name: 'Claude Opus 4.6',
              inputPricePerToken: 0.000005,
              outputPricePerToken: 0.000025,
            },
          ];
        }
        return [];
      });

      await service.reload();

      const bare = service.getByModel('claude-opus-4-6');
      expect(bare).toBeDefined();
      expect(bare!.source).toBe('models.dev');
      expect(bare!.input_price_per_token).toBe(0.000005);
    });

    it('treats a single zero side (input=0 but output>0) as NOT zero-pricing', async () => {
      // The guard requires BOTH input and output to be zero for the
      // "isZeroPricing" check. A model with one side non-zero is real
      // pricing and should be allowed to overwrite.
      mockGetAll.mockReturnValue(
        new Map<string, OpenRouterPricingEntry>([
          ['anthropic/claude-half', makeEntry(0.001, 0.002)],
        ]),
      );

      mockModelsDevSync.getModelsForProvider.mockImplementation((providerId: string) => {
        if (providerId === 'anthropic') {
          return [
            {
              id: 'claude-half',
              name: 'Claude Half',
              inputPricePerToken: 0,
              outputPricePerToken: 0.005,
            },
          ];
        }
        return [];
      });

      await service.reload();

      const entry = service.getByModel('claude-half');
      expect(entry).toBeDefined();
      // models.dev wins because output is non-zero → not "zero pricing".
      expect(entry!.source).toBe('models.dev');
      expect(entry!.input_price_per_token).toBe(0);
      expect(entry!.output_price_per_token).toBe(0.005);
    });

    it('treats OpenRouter zero-input pricing as NOT "real pricing" so models.dev can win', async () => {
      // hasRealPricing = (existing.input ?? 0) > 0. So if OpenRouter
      // already has input=0 (regardless of output), the guard considers
      // it "no real pricing" and models.dev — even at $0 — overwrites.
      // This pins that boundary so the conditional doesn't drift.
      mockGetAll.mockReturnValue(
        new Map<string, OpenRouterPricingEntry>([
          ['anthropic/claude-free-input', makeEntry(0, 0.002)],
        ]),
      );

      mockModelsDevSync.getModelsForProvider.mockImplementation((providerId: string) => {
        if (providerId === 'anthropic') {
          return [
            {
              id: 'claude-free-input',
              name: 'Claude Free Input',
              inputPricePerToken: 0,
              outputPricePerToken: 0,
            },
          ];
        }
        return [];
      });

      await service.reload();

      const entry = service.getByModel('claude-free-input');
      expect(entry).toBeDefined();
      expect(entry!.source).toBe('models.dev');
      expect(entry!.input_price_per_token).toBe(0);
      expect(entry!.output_price_per_token).toBe(0);
    });
  });
});

import { ModelPricingCacheService } from './model-pricing-cache.service';
import { PricingSyncService, OpenRouterPricingEntry } from '../database/pricing-sync.service';
import { ModelsDevSyncService } from '../database/models-dev-sync.service';
import { ProviderModelRegistryService } from '../model-discovery/provider-model-registry.service';

/**
 * Tests for time-of-day pricing tiers flowing from the models.dev sync into
 * `PricingEntry.time_tiers` (peak/off-peak providers like DeepSeek V4).
 *
 * The transport rule is pinned here too: the OpenRouter-prefixed key means
 * the request rode through OpenRouter, which bills its own flat rate, so the
 * prefixed copy of the entry must NOT carry the lab's peak-hour schedule.
 */

const DEEPSEEK_TIME_TIER = {
  windows: ['01:00-04:00', '06:00-10:00'],
  days: [1, 2, 3, 4, 5],
  inputPricePerToken: 0.44 / 1_000_000,
  outputPricePerToken: 1.32 / 1_000_000,
  cacheReadPricePerToken: 0.014 / 1_000_000,
  cacheWritePricePerToken: null,
};

describe('ModelPricingCacheService — time-of-day pricing tiers', () => {
  let service: ModelPricingCacheService;
  let mockGetAll: jest.Mock;
  let mockModelsDevSync: {
    lookupModel: jest.Mock;
    getModelsForProvider: jest.Mock;
    isProviderSupported: jest.Mock;
    whenInitialized: jest.Mock;
  };

  beforeEach(() => {
    mockGetAll = jest.fn().mockReturnValue(new Map<string, OpenRouterPricingEntry>());
    const mockPricingSync = {
      getAll: mockGetAll,
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    mockModelsDevSync = {
      lookupModel: jest.fn().mockReturnValue(null),
      getModelsForProvider: jest.fn().mockImplementation((providerId: string) => {
        if (providerId !== 'deepseek') return [];
        return [
          {
            id: 'deepseek-v4-flash',
            name: 'DeepSeek V4 Flash',
            inputPricePerToken: 0.22 / 1_000_000,
            outputPricePerToken: 0.66 / 1_000_000,
            cacheReadPricePerToken: 0.007 / 1_000_000,
            timeTiers: [DEEPSEEK_TIME_TIER],
          },
          {
            id: 'deepseek-chat',
            name: 'DeepSeek Chat',
            inputPricePerToken: 0.14 / 1_000_000,
            outputPricePerToken: 0.28 / 1_000_000,
          },
        ];
      }),
      isProviderSupported: jest.fn().mockReturnValue(false),
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    const mockRegistry = {
      isModelConfirmed: jest.fn().mockReturnValue(null),
      getConfirmedModels: jest.fn().mockReturnValue(null),
      registerModels: jest.fn(),
    };
    service = new ModelPricingCacheService(
      mockPricingSync as unknown as PricingSyncService,
      mockModelsDevSync as unknown as ModelsDevSyncService,
      mockRegistry as unknown as ProviderModelRegistryService,
    );
  });

  it('maps models.dev time tiers onto the bare-key pricing entry', async () => {
    await service.reload();

    const entry = service.getByModel('deepseek-v4-flash');
    expect(entry).toBeDefined();
    expect(entry!.time_tiers).toEqual([
      {
        windows: ['01:00-04:00', '06:00-10:00'],
        days: [1, 2, 3, 4, 5],
        input_price_per_token: 0.44 / 1_000_000,
        output_price_per_token: 1.32 / 1_000_000,
        cache_read_price_per_token: 0.014 / 1_000_000,
        cache_write_price_per_token: null,
      },
    ]);
    expect(entry!.input_price_per_token).toBe(0.22 / 1_000_000);
  });

  it('leaves time_tiers undefined for models without a schedule', async () => {
    await service.reload();

    expect(service.getByModel('deepseek-chat')!.time_tiers).toBeUndefined();
  });

  it('carries a schedule with no weekdays through as null, meaning every day', async () => {
    // `days` is optional upstream and an absent list means the windows apply
    // on all seven days. That has to survive the mapping as an explicit null
    // rather than vanishing, because the cost calculator reads the field to
    // decide whether to narrow the window at all.
    mockModelsDevSync.getModelsForProvider.mockImplementation((providerId: string) =>
      providerId === 'deepseek'
        ? [
            {
              id: 'deepseek-v4-flash',
              name: 'DeepSeek V4 Flash',
              inputPricePerToken: 0.22 / 1_000_000,
              outputPricePerToken: 0.66 / 1_000_000,
              cacheReadPricePerToken: 0.007 / 1_000_000,
              timeTiers: [{ ...DEEPSEEK_TIME_TIER, days: null }],
            },
          ]
        : [],
    );

    await service.reload();

    expect(service.getByModel('deepseek-v4-flash')!.time_tiers![0].days).toBeNull();
  });

  it('keeps the OpenRouter entry on the prefixed key and only drops the tiers', async () => {
    // OpenRouter also lists the model, so the prefixed key pre-exists. Pricing
    // follows transport: the OR entry keeps OR's own flat rate — the overlay
    // must not replace it with the lab's prices, only guarantee no tiers.
    mockGetAll.mockReturnValue(
      new Map<string, OpenRouterPricingEntry>([
        ['deepseek/deepseek-v4-flash', { input: 0.3 / 1_000_000, output: 0.9 / 1_000_000 }],
      ]),
    );

    await service.reload();

    const prefixed = service.getByModel('deepseek/deepseek-v4-flash');
    expect(prefixed).toBeDefined();
    expect(prefixed!.time_tiers).toBeNull();
    // OpenRouter's flat rate survives the models.dev overlay.
    expect(prefixed!.input_price_per_token).toBe(0.3 / 1_000_000);
    expect(prefixed!.output_price_per_token).toBe(0.9 / 1_000_000);
    // The bare key still carries the schedule for direct-API traffic.
    expect(service.getByModel('deepseek-v4-flash')!.time_tiers).toHaveLength(1);
  });
});

import { Repository } from 'typeorm';
import { ModelPricingCacheService } from './model-pricing-cache.service';
import { PricingSyncService, OpenRouterPricingEntry } from '../database/pricing-sync.service';
import { ModelsDevSyncService } from '../database/models-dev-sync.service';
import { ProviderModelRegistryService } from '../model-discovery/provider-model-registry.service';
import { CustomProvider } from '../entities/custom-provider.entity';

function makeEntry(input: number, output: number): OpenRouterPricingEntry {
  return { input, output };
}

function makeCustomProviderRepo(rows: CustomProvider[] | Error) {
  const find = jest.fn();
  if (rows instanceof Error) {
    find.mockRejectedValue(rows);
  } else {
    find.mockResolvedValue(rows);
  }
  return { find } as unknown as Repository<CustomProvider>;
}

function makeMockRegistry() {
  return {
    isModelConfirmed: jest.fn().mockReturnValue(null),
    getConfirmedModels: jest.fn().mockReturnValue(null),
    registerModels: jest.fn(),
  };
}

function makeMockModelsDevSync() {
  return {
    lookupModel: jest.fn().mockReturnValue(null),
    getModelsForProvider: jest.fn().mockReturnValue([]),
    isProviderSupported: jest.fn().mockReturnValue(false),
    whenInitialized: jest.fn().mockResolvedValue(undefined),
  };
}

/** Flush the fire-and-forget warmup chain (whenInitialized + reload microtasks). */
function flushWarmup(): Promise<void> {
  return new Promise((resolve) => setImmediate(resolve));
}

describe('ModelPricingCacheService', () => {
  let service: ModelPricingCacheService;
  let mockGetAll: jest.Mock;
  let mockRegistry: ReturnType<typeof makeMockRegistry>;
  let mockModelsDevSync: ReturnType<typeof makeMockModelsDevSync>;
  let mockPricingSync: { getAll: jest.Mock; whenInitialized: jest.Mock };

  beforeEach(() => {
    mockGetAll = jest.fn().mockReturnValue(new Map<string, OpenRouterPricingEntry>());
    mockPricingSync = {
      getAll: mockGetAll,
      whenInitialized: jest.fn().mockResolvedValue(undefined),
    };
    mockModelsDevSync = makeMockModelsDevSync();
    mockRegistry = makeMockRegistry();
    service = new ModelPricingCacheService(
      mockPricingSync as unknown as PricingSyncService,
      mockModelsDevSync as unknown as ModelsDevSyncService,
      mockRegistry as unknown as ProviderModelRegistryService,
    );
  });

  describe('onApplicationBootstrap', () => {
    it('warms up the cache after the upstream syncs settle', async () => {
      const spy = jest.spyOn(service, 'reload').mockResolvedValue();
      // onApplicationBootstrap is fire-and-forget so it can't delay boot (#1894).
      service.onApplicationBootstrap();
      await flushWarmup();
      expect(mockPricingSync.whenInitialized).toHaveBeenCalledTimes(1);
      expect(mockModelsDevSync.whenInitialized).toHaveBeenCalledTimes(1);
      expect(spy).toHaveBeenCalledTimes(1);
    });

    it('swallows errors when reload fails during warmup', async () => {
      jest.spyOn(service, 'reload').mockRejectedValue(new Error('boom'));
      service.onApplicationBootstrap();
      // warmup's try/catch handles it — no unhandled rejection
      await expect(flushWarmup()).resolves.toBeUndefined();
    });

    it('tolerates a missing models.dev sync', async () => {
      const soloService = new ModelPricingCacheService(
        mockPricingSync as unknown as PricingSyncService,
        null,
        mockRegistry as unknown as ProviderModelRegistryService,
      );
      const spy = jest.spyOn(soloService, 'reload').mockResolvedValue();
      soloService.onApplicationBootstrap();
      await flushWarmup();
      expect(spy).toHaveBeenCalledTimes(1);
    });
  });

  describe('scheduledReload', () => {
    it('should call reload()', async () => {
      const spy = jest.spyOn(service, 'reload').mockResolvedValue();
      await service.scheduledReload();
      expect(spy).toHaveBeenCalledTimes(1);
    });
  });

  describe('reload', () => {
    it('should attribute supported providers from OpenRouter data', async () => {
      const orMap = new Map<string, OpenRouterPricingEntry>([
        ['openai/gpt-4o', makeEntry(0.0000025, 0.00001)],
        ['anthropic/claude-opus-4-6', makeEntry(0.000015, 0.000075)],
        ['google/gemini-2.5-pro', makeEntry(0.000003, 0.000015)],
      ]);
      mockGetAll.mockReturnValue(orMap);
      await service.reload();

      expect(service.getByModel('openai/gpt-4o')!.provider).toBe('OpenAI');
      expect(service.getByModel('anthropic/claude-opus-4-6')!.provider).toBe('Anthropic');
      expect(service.getByModel('google/gemini-2.5-pro')!.provider).toBe('Google');
    });

    it('should keep unsupported vendors under OpenRouter', async () => {
      const orMap = new Map<string, OpenRouterPricingEntry>([
