  it('fails closed when the cached-key activity recheck cannot reach the database', async () => {
    const token = 'mnfst_cached-key-db-error';
    mockGetMany.mockResolvedValue([
      {
        id: 'key-db-error',
        tenant_id: 'tenant-1',
        agent_id: 'agent-1',
        key_hash: hashKey(token),
        expires_at: null,
